import React from "react";
import "./LeadKanban.css";

const statuses = [
  { key: "new", label: "Mới" },
  { key: "processing", label: "Đang xử lý" },
  { key: "converted", label: "Chuyển đổi" },
  { key: "lost", label: "Mất" },
];

const LeadKanban = ({ leads, onStatusChange, onDelete }) => {
  return (
    <div className="kanban-container">
      {statuses.map((s) => (
        <div key={s.key} className="kanban-column">
          <h3>{s.label}</h3>
          {leads
            .filter((lead) => lead.status === s.key)
            .map((lead) => (
              <div key={lead._id} className="kanban-card">
                <h4>{lead.name}</h4>
                <p>{lead.email}</p>
                <p>{lead.phone}</p>
                <select
                  value={lead.status}
                  onChange={(e) => onStatusChange(lead._id, e.target.value)}
                >
                  {statuses.map((st) => (
                    <option key={st.key} value={st.key}>
                      {st.label}
                    </option>
                  ))}
                </select>
                <button onClick={() => onDelete(lead._id)}>Xóa</button>
              </div>
            ))}
        </div>
      ))}
    </div>
  );
};

export default LeadKanban;
